import _ from 'lodash';
import classNames from 'classnames/bind';

import appStyles from 'css/app';

const styles = classNames.bind( appStyles );
const { Component, createRef } = wp.element;

/**
 * Display modal dialog box with confirmation
 */

export default class ModalDialog extends Component {
	modalRef = createRef();
	previousActiveElement = null;

	/**
	 * Get the dismiss button from props
	 *
	 * @return {Object} The dismiss button object or empty object
	 */
	getDismissButton() {
		let dismissButton = _.find( this.props.buttons, { dismissModal: true } ) || {};

		// If multiple dismiss buttons are found, take the first one.
		if ( _.isArray( dismissButton ) ) {
			dismissButton = dismissButton.shift();
		}

		return dismissButton;
	}

	/**
	 * Get all focusable elements within the modal
	 *
	 * @return {Array} Array of focusable elements
	 */
	getFocusableElements() {
		if ( ! this.modalRef.current ) {
			return [];
		}

		const focusableSelectors = [
			'button:not([disabled])',
			'[href]',
			'input:not([disabled])',
			'select:not([disabled])',
			'textarea:not([disabled])',
			'[tabindex]:not([tabindex="-1"])',
		].join( ', ' );

		return Array.from( this.modalRef.current.querySelectorAll( focusableSelectors ) );
	}

	/**
	 * Handle keyboard events for focus trap and dismiss
	 * Using arrow function to maintain `this` binding
	 *
	 * @param {Object} event Keydown event
	 */
	handleKeyDown = ( event ) => {
		// Dismiss modal on Escape.
		const dismissButton = this.getDismissButton();

		if ( event.key === 'Escape' && dismissButton.action ) {
			dismissButton.action();
			return;
		}

		// Focus trap on Tab.
		if ( event.key === 'Tab' ) {
			const focusableElements = this.getFocusableElements();

			if ( focusableElements.length === 0 ) {
				event.preventDefault();
				return;
			}

			const firstElement = focusableElements[ 0 ];
			const lastElement = focusableElements[ focusableElements.length - 1 ];

			// Shift+Tab on first element -> go to last
			if ( event.shiftKey && document.activeElement === firstElement ) {
				event.preventDefault();
				lastElement.focus();
			}
			// Tab on last element -> go to first
			else if ( ! event.shiftKey && document.activeElement === lastElement ) {
				event.preventDefault();
				firstElement.focus();
			}
		}
	};

	/**
	 * Add event listener on component mount and set initial focus
	 */
	componentDidMount() {
		// Store the previously focused element to restore on unmount
		this.previousActiveElement = document.activeElement;

		document.addEventListener( 'keydown', this.handleKeyDown );

		// Focus the first focusable element in the modal
		requestAnimationFrame( () => {
			const focusableElements = this.getFocusableElements();
			if ( focusableElements.length > 0 ) {
				focusableElements[ 0 ].focus();
			}
		} );
	}

	/**
	 * Remove event listener on component unmount and restore focus
	 */
	componentWillUnmount() {
		document.removeEventListener( 'keydown', this.handleKeyDown );

		// Restore focus to the previously focused element if it's still in the DOM
		if (
			this.previousActiveElement &&
			this.previousActiveElement.focus &&
			document.body.contains( this.previousActiveElement )
		) {
			this.previousActiveElement.focus();
		}
	}

	/**
	 * Render modal dialog
	 *
	 * @return {Object} JSX markup
	 */
	render() {
		return (
			<section data-automation-id={ this.props.automationId } className={ styles( 'modal-dialog', 'section' ) }>
				<div
					className={ styles( 'modal', 'is-active' ) }
					ref={ this.modalRef }
					role="dialog"
					aria-modal="true"
					aria-label={ this.props.ariaLabel || 'Dialog' }
				>
					<div className={ styles( 'modal-background' ) } />
					<div className={ styles( 'modal-card' ) }>
						<section className={ styles( 'modal-card-body' ) }>
							{ this.props.content }
						</section>
						{ this.props.buttons &&
						<footer className={ styles( 'modal-card-foot' ) }>
							{ this.props.buttons.map( ( button, index ) =>
								<button
									ref={ button.ref }
									key={ `model-dialog-button-${ index }` }
									disabled={ button.disabled }
									className={ styles( 'button', button.style ) }
									data-automation-id={ button.automationId }
									onClick={ button.action }
									tabIndex={ 0 }
								>
									{ button.label }
								</button>,
							) }
						</footer>
						}
					</div>
				</div>
			</section>
		);
	}
}
