import _ from 'lodash';
import { getFormField } from 'js/helpers/form-field-manipulations';

const PROFILE_VERSION = 1;
const PROFILE_TYPE = 'import_profile';

const getFieldValue = ( field, key, fallback = '' ) => {
	if ( ! field || field[ key ] === undefined || field[ key ] === null ) {
		return fallback;
	}

	return field[ key ];
};

const getInputIds = ( inputs ) => {
	if ( ! inputs ) {
		return [];
	}

	return Object.values( inputs )
		.map( ( input ) => getFieldValue( input, 'id', '' ) )
		.filter( ( id ) => String( id ) !== '' )
		.map( ( id ) => String( id ) )
		.sort( ( a, b ) => Number( a ) - Number( b ) );
};

const getChoiceValues = ( choices ) => {
	if ( ! choices ) {
		return [];
	}

	return Object.values( choices )
		.map( ( choice ) => {
			const value = getFieldValue( choice, 'value', '' );

			if ( String( value ) !== '' ) {
				return String( value );
			}

			return String( getFieldValue( choice, 'text', '' ) );
		} )
		.sort();
};

const getFieldFormat = ( field ) => {
	const formatKeys = {
		date: 'dateFormat',
		time: 'timeFormat',
		phone: 'phoneFormat',
		number: 'numberFormat',
	};
	const key = formatKeys[ field.type ];

	return key ? String( getFieldValue( field, key, '' ) ) : '';
};

const getFieldFingerprint = ( field ) => {
	const inputs = getInputIds( field.inputs );
	const choices = getChoiceValues( field.choices );
	const required = getFieldValue( field, 'isRequired' ) || getFieldValue( field, 'required' );

	return [
		field.id,
		field.type || '',
		required ? '1' : '0',
		inputs.join( ',' ),
		choices.join( ',' ),
		getFieldFormat( field ),
	].join( ':' );
};

const normalizeHeader = ( header, index ) => {
	let normalized = String( header === undefined || header === null ? '' : header );

	if ( index === 0 ) {
		normalized = normalized.replace( /^\uFEFF/, '' );
	}

	return normalized.trim().toLowerCase();
};

/**
 * Compute a deterministic hash of form field structure.
 *
 * @since 2.11.0
 *
 * @param {Object} formFields Keyed object of form fields.
 * @return {string} 8-character hex hash.
 */
export const computeFormHash = ( formFields ) => {
	const entries = Object.values( formFields )
		.filter( ( f ) => f && f.id !== undefined && ! isNaN( Number( f.id ) ) )
		.sort( ( a, b ) => Number( a.id ) - Number( b.id ) )
		.map( ( f ) => getFieldFingerprint( f ) );

	const str = entries.join( '|' );
	let hash = 5381;

	for ( let i = 0; i < str.length; i++ ) {
		hash = ( ( hash << 5 ) + hash + str.charCodeAt( i ) ) >>> 0;
	}

	return hash.toString( 16 ).padStart( 8, '0' );
};

/**
 * Build a profile JSON object from current import state.
 *
 * @since 2.11.0
 *
 * @param {Object} params
 * @param {Object} params.importData The app context importData.
 * @param {Array}  params.selectedColumnFields Step 3 column fields state.
 * @param {Array}  params.csvHeaders Array of CSV header strings.
 * @param {Object} params.options Step 4 options state (native shape).
 * @return {Object} The profile object.
 */
export const buildProfile = ( { importData, selectedColumnFields, csvHeaders, options } ) => {
	const formHash = computeFormHash( importData.form.fields );

	const columns = csvHeaders.map( ( header, index ) => ( { header, index } ) );
	const fieldsByColumn = _.keyBy( selectedColumnFields, 'columnIndex' );

	const schema = ( importData.schema || [] ).map( ( rule ) => {
		const field = fieldsByColumn[ rule.column ];
		const type = field && field._data ? field._data.type : null;

		if ( ! type ) {
			return { ...rule };
		}

		return { ...rule, type };
	} );

	// Strip _data from selectedColumnFields.
	const cleanedFields = selectedColumnFields.map( ( field ) => {
		const cleaned = { ...field };
		delete cleaned._data;
		return cleaned;
	} );

	return {
		version: PROFILE_VERSION,
		type: PROFILE_TYPE,
		formId: importData.form.id,
		formTitle: importData.form.title,
		formHash,
		columns,
		schema,
		selectedColumnFields: cleanedFields,
		options: options || {},
	};
};

/**
 * Validate a profile JSON object.
 *
 * @since 2.11.0
 *
 * @param {Object} json The parsed JSON.
 * @return {Object} { valid: boolean, error?: string }
 */
export const validateProfile = ( json ) => {
	if ( ! json || typeof json !== 'object' ) {
		return { valid: false, error: 'Invalid JSON.' };
	}

	if ( json.version !== PROFILE_VERSION ) {
		return { valid: false, error: `Unsupported profile version: ${ json.version }.` };
	}

	if ( json.type !== PROFILE_TYPE ) {
		return { valid: false, error: 'Not an import profile file.' };
	}

	if ( ! json.formId ) {
		return { valid: false, error: 'Profile is missing form ID.' };
	}

	if ( ! Array.isArray( json.columns ) || ! json.columns.length ) {
		return { valid: false, error: 'Profile is missing column definitions.' };
	}

	if ( ! Array.isArray( json.schema ) ) {
		return { valid: false, error: 'Profile is missing field mapping schema.' };
	}

	if ( ! Array.isArray( json.selectedColumnFields ) ) {
		return { valid: false, error: 'Profile is missing column field data.' };
	}

	return { valid: true };
};

/**
 * Match profile columns to current CSV headers.
 *
 * @since 2.11.0
 *
 * @param {Array} profileColumns Array of { header, index } from profile.
 * @param {Array} currentHeaders Array of current CSV header strings.
 * @return {Object} { matched: Map, matchType: Map, unmatched: number[] }
 */
export const matchColumns = ( profileColumns, currentHeaders ) => {
	const matched = new Map();
	const matchType = new Map();
	const unmatchedProfileIndices = [];

	// Build a lookup of current headers by name for O(1) matching.
	const headerToCurrentIndex = new Map();

	currentHeaders.forEach( ( header, index ) => {
		const normalized = normalizeHeader( header, index );

		// Only store first occurrence to avoid ambiguity.
		if ( ! headerToCurrentIndex.has( normalized ) ) {
			headerToCurrentIndex.set( normalized, index );
		}
	} );

	const usedCurrentIndices = new Set();

	// Pass 1: match by header name.
	profileColumns.forEach( ( col ) => {
		const currentIndex = headerToCurrentIndex.get( normalizeHeader( col.header, col.index ) );

		if ( currentIndex !== undefined && ! usedCurrentIndices.has( currentIndex ) ) {
			matched.set( col.index, currentIndex );
			matchType.set( col.index, 'name' );
			usedCurrentIndices.add( currentIndex );
		}
	} );

	// Pass 2: position fallback for unmatched.
	profileColumns.forEach( ( col ) => {
		if ( matched.has( col.index ) ) {
			return;
		}

		if ( col.index < currentHeaders.length && ! usedCurrentIndices.has( col.index ) ) {
			matched.set( col.index, col.index );
			matchType.set( col.index, 'position' );
			usedCurrentIndices.add( col.index );
		} else {
			unmatchedProfileIndices.push( col.index );
		}
	} );

	return { matched, matchType, unmatched: unmatchedProfileIndices };
};

/**
 * Apply a loaded profile to build new selectedColumnFields.
 *
 * @since 2.11.0
 *
 * @param {Object} profile The loaded profile object.
 * @param {Object} matchResult Result from matchColumns().
 * @param {Object} formFields Keyed form fields object.
 * @param {number} currentColumnCount Number of columns in current CSV.
 * @return {Object} New selectedColumnFields array and warnings.
 */
export const applyProfileToColumnFields = ( profile, matchResult, formFields, currentColumnCount ) => {
	const { matched } = matchResult;
	const warnings = [];

	// Build reverse map: currentIndex → profileIndex.
	const currentToProfile = new Map();

	matched.forEach( ( currentIdx, profileIdx ) => {
		currentToProfile.set( currentIdx, profileIdx );
	} );

	// Index profile's selectedColumnFields by their original columnIndex.
	const profileFieldsByIndex = _.keyBy( profile.selectedColumnFields, 'columnIndex' );

	const selectedColumnFields = _.times( currentColumnCount, ( currentIdx ) => {
		const profileIdx = currentToProfile.get( currentIdx );

		if ( profileIdx !== undefined && profileFieldsByIndex[ profileIdx ] ) {
			const saved = profileFieldsByIndex[ profileIdx ];
			const fieldId = saved.id || '';
			let fieldData = {};

			if ( fieldId ) {
				try {
					fieldData = getFormField( fieldId, formFields );
				} catch ( err ) {
					fieldData = {};
				}
			}

			if ( fieldId && _.isEmpty( fieldData ) ) {
				warnings.push( {
					columnIndex: currentIdx,
				} );

				return {
					id: '',
					columnIndex: currentIdx,
					importEnabled: saved.importEnabled !== false,
					ignore: saved.ignore || false,
					_data: {},
				};
			}

			return {
				id: fieldId,
				columnIndex: currentIdx,
				importEnabled: saved.importEnabled !== false,
				ignore: saved.ignore || false,
				_data: fieldData,
			};
		}

		// Unmatched column: default to unmapped.
		return {
			id: '',
			columnIndex: currentIdx,
			importEnabled: true,
			ignore: false,
			_data: {},
		};
	} );

	return { selectedColumnFields, warnings };
};

/**
 * Trigger a browser download of the profile JSON file.
 *
 * @since 2.11.0
 *
 * @param {Object} profile The profile object.
 * @param {number} formId The form ID.
 * @param {string} formHash The form hash.
 */
export const downloadProfile = ( profile, formId, formHash ) => {
	const json = JSON.stringify( profile, null, 2 );
	const blob = new Blob( [ json ], { type: 'application/json' } );
	const url = URL.createObjectURL( blob );

	const a = document.createElement( 'a' );
	const ts = new Date().toISOString().slice( 0, 16 ).replace( /[-:T]/g, '' ).slice( 0, 12 );

	a.href = url;
	a.download = `form_${ formId }_import_profile_${ formHash }_${ ts }.json`;
	a.click();

	setTimeout( () => URL.revokeObjectURL( url ), 1000 );
};
