import _ from 'lodash';

/**
 * @typedef {Object} ValidationContext
 * @property {Object} field
 * @property {Object} form
 * @property {number} columnIndex
 * @property {Array} importData
 * @property {Array} selectedColumnFields
 */

/**
 * @typedef {Object} ValidationGroup
 * @property {string} title
 * @property {string} description
 * @property {string} color
 * @property {string} iconKey
 * @property {boolean} actionable
 */

/**
 * @typedef {Object} ValidationRule
 * @property {number} order
 * @property {Function} appliesTo
 * @property {Function=} validateCell
 * @property {Function=} validateColumn
 * @property {Function=} getColumnDetails
 * @property {Function|string=} message
 * @property {Function|string=} details
 * @property {string=} action
 * @property {string=} severity
 * @property {Function|string=} badgeText
 * @property {string=} badgeModifier
 * @property {ValidationGroup=} group
 */

const VALIDATION_I18N = {
	duplicate: {
		message: { path: 'map_fields.duplicate_field_error', fallback: 'Duplicate field mapping' },
		details: { path: 'map_fields.duplicate_field_details', fallback: 'This field is already mapped to: %s' },
		badge: { path: 'map_fields.error_duplicate', fallback: 'Duplicate' },
		group: {
			title: { path: 'map_fields.duplicate_errors_title', fallback: 'Duplicate Field Mappings' },
			description: { path: 'map_fields.duplicate_errors_desc', fallback: 'Each form field can only be mapped once. Remove duplicate mappings to continue.' },
		},
	},
	invalid_date: {
		message: { path: 'date_format_filter.invalid_date', fallback: 'Date Not Recognized' },
		details: { path: 'date_format_filter.invalid_date_details', fallback: 'Value could not be parsed as a date.' },
		badge: { path: 'map_fields.error_invalid_date', fallback: 'Invalid Date' },
		group: {
			title: { path: 'map_fields.date_errors_title', fallback: 'Invalid Date Format' },
			description: { path: 'map_fields.date_errors_desc', fallback: 'Date columns must match the expected format (e.g., YYYY-MM-DD).' },
		},
	},
	invalid_time: {
		message: { path: 'time_format_filter.invalid_time', fallback: 'Time Not Recognized' },
		details: { path: 'time_format_filter.invalid_time_details', fallback: 'Value could not be parsed as a time.' },
		badge: { path: 'map_fields.error_invalid_time', fallback: 'Invalid Time' },
		group: {
			title: { path: 'map_fields.time_errors_title', fallback: 'Invalid Time Format' },
			description: { path: 'map_fields.time_errors_desc', fallback: 'Time columns must match the expected format (e.g., HH:MM AM/PM).' },
		},
	},
	invalid_list: {
		message: { path: 'list_json_filter.invalid_list', fallback: 'List data not recognized' },
		details: { path: 'list_json_filter.invalid_list_details', fallback: 'Value is not valid JSON for a list field.' },
		badge: { path: 'map_fields.error_invalid_format', fallback: 'Invalid Format' },
		group: {
			title: { path: 'map_fields.list_errors_title', fallback: 'Invalid List Format' },
			description: { path: 'map_fields.list_errors_desc', fallback: 'List data must be properly formatted JSON arrays.' },
		},
	},
	invalid_notes: {
		message: { path: 'entry_notes_filter.invalid_notes', fallback: 'Entry notes not recognized' },
		details: { path: 'entry_notes_filter.invalid_notes_details', fallback: 'Value is not valid JSON for entry notes.' },
		badge: { path: 'map_fields.error_invalid_format', fallback: 'Invalid Format' },
		group: {
			title: { path: 'map_fields.notes_errors_title', fallback: 'Invalid Notes Format' },
			description: { path: 'map_fields.notes_errors_desc', fallback: 'Notes must be in a valid format for import.' },
		},
	},
	invalid_email: {
		message: { path: 'map_fields.email_invalid_warning', fallback: 'Invalid Email Format' },
		details: { path: 'map_fields.email_invalid_details', fallback: 'Value does not appear to be a valid email address.' },
		badge: { path: 'map_fields.error_invalid_email_format', fallback: 'Invalid Email Format' },
		group: {
			title: { path: 'map_fields.email_invalid_title', fallback: 'Invalid Email Format' },
			description: { path: 'map_fields.email_invalid_details', fallback: 'Value does not appear to be a valid email address.' },
		},
	},
	rejected_email: {
		message: { path: 'map_fields.email_rejected_warning', fallback: 'Email will be rejected by Gravity Forms' },
		details: { path: 'map_fields.email_rejected_patterns_info', fallback: 'Gravity Forms will reject emails matching certain patterns.' },
		badge: { path: 'map_fields.error_invalid_email', fallback: 'Invalid Email' },
		group: {
			title: { path: 'map_fields.email_rejected_title', fallback: 'Email Will Be Rejected' },
			description: { path: 'map_fields.email_rejected_patterns_info', fallback: 'Gravity Forms will reject emails matching certain patterns.' },
		},
	},
	invalid_number: {
		message: { path: 'map_fields.number_invalid_warning', fallback: 'Invalid Number Value' },
		details: { path: 'map_fields.number_invalid_details', fallback: 'Non-numeric values will fail to import.' },
		badge: { path: 'map_fields.error_invalid_number', fallback: 'Invalid Number' },
		group: {
			title: { path: 'map_fields.number_invalid_title', fallback: 'Invalid Number Value' },
			description: { path: 'map_fields.number_invalid_info', fallback: 'Number fields only accept numeric values.' },
		},
	},
	invalid_url: {
		message: { path: 'map_fields.url_invalid_warning', fallback: 'Invalid URL Value' },
		details: { path: 'map_fields.url_invalid_details', fallback: 'Values don\'t appear to be valid URLs.' },
		badge: { path: 'map_fields.error_invalid_url', fallback: 'Invalid URL' },
		group: {
			title: { path: 'map_fields.url_invalid_title', fallback: 'Invalid URL Value' },
			description: { path: 'map_fields.url_invalid_info', fallback: 'URL fields require valid URL values.' },
		},
	},
	invalid_phone: {
		message: { path: 'map_fields.phone_invalid_warning', fallback: 'Invalid Phone Number' },
		details: { path: 'map_fields.phone_invalid_details', fallback: 'Values don\'t appear to be valid phone numbers.' },
		badge: { path: 'map_fields.error_invalid_phone', fallback: 'Invalid Phone' },
		group: {
			title: { path: 'map_fields.phone_invalid_title', fallback: 'Invalid Phone Number' },
			description: { path: 'map_fields.phone_invalid_info', fallback: 'Phone fields require valid phone number values.' },
		},
	},
	invalid_ip: {
		message: { path: 'map_fields.ip_invalid_warning', fallback: 'Invalid IP Address' },
		details: { path: 'map_fields.ip_invalid_details', fallback: 'Values don\'t appear to be valid IPv4 or IPv6 addresses.' },
		badge: { path: 'map_fields.error_invalid_ip', fallback: 'Invalid IP' },
		group: {
			title: { path: 'map_fields.ip_invalid_title', fallback: 'Invalid IP Address' },
			description: { path: 'map_fields.ip_invalid_info', fallback: 'IP fields require valid IPv4 or IPv6 values.' },
		},
	},
};

const getLocalizationText = ( pluginData, descriptor ) => {
	if ( ! descriptor ) {
		return '';
	}

	return _.get( pluginData.localization, descriptor.path, descriptor.fallback );
};

export const createValidationUtils = ( options ) => {
	const {
		pluginData,
		helpers,
		constants,
	} = options;
	const sampleRows = options.validationSampleRows || 50;

	const {
		isFieldMapped,
		isEmailField,
		isNumberField,
		isUrlField,
		isPhoneField,
		isIpField,
		isValueInvalidNumber,
		isValueInvalidPhone,
		isValueInvalidIp,
		looksLikeEmail,
		looksLikeUrl,
		looksLikeDate,
		looksLikeTime,
		tryParseDate,
		tryParseTime,
	} = helpers;

	const {
		nonDuplicableTypes,
		ignoreFieldId,
		defaultColumnField,
	} = constants;

	const rejectablePatterns = pluginData.rejectable_email_patterns || [];
	const t = ( descriptor ) => getLocalizationText( pluginData, descriptor );
	const i18n = VALIDATION_I18N;

	let validationConfig;

	const isEmptyValidationValue = ( value ) => {
		if ( value === null || value === undefined ) {
			return true;
		}

		if ( typeof value === 'string' ) {
			return value.trim() === '';
		}

		return false;
	};

	const scanInvalidValues = ( columnIndex, importData, validateCell ) => {
		const result = {
			count: 0,
			examples: [],
			total: 0,
			firstInvalid: null,
		};

		if ( ! importData || importData.length < 2 || typeof validateCell !== 'function' ) {
			return result;
		}

		const maxRows = Math.min( importData.length, sampleRows + 1 );
		result.total = maxRows - 1; // Exclude header row.

		for ( let i = 1; i < maxRows; i++ ) {
			const value = importData[ i ] && importData[ i ][ columnIndex ];

			if ( isEmptyValidationValue( value ) ) {
				continue;
			}

			const displayValue = typeof value === 'string' ? value.trim() : String( value );

			if ( validateCell( value ) ) {
				result.count++;
				if ( result.firstInvalid === null ) {
					result.firstInvalid = displayValue;
				}

				if ( result.examples.length < 3 ) {
					const example = displayValue.length > 30
						? displayValue.substring( 0, 30 ) + '...'
						: displayValue;
					result.examples.push( example );
				}
			}
		}

		return result;
	};

	const getValidationConfig = () => {
		if ( validationConfig ) {
			return validationConfig;
		}

		validationConfig = {
			invalid_date: {
				order: 10,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && context.field && context.field._data && context.field._data.filter === 'dateFormat',
				validateCell: ( value, context ) => {
					const stringValue = String( value ).trim();
					if ( ! stringValue ) {
						return false;
					}

					const lowerValue = stringValue.toLowerCase();
					if ( lowerValue.includes( 'invalid' ) ||
						 lowerValue === 'nan' ||
						 lowerValue === 'null' ||
						 lowerValue === 'undefined' ) {
						return true;
					}

					const { _data: { filterData } = {} } = context.field || {};
					const format = filterData && filterData.format ? filterData.format.trim() : '';

					if ( format ) {
						const standardFormats = [
							'm/d/Y', 'd/m/Y', 'd-m-Y', 'd.m.Y',
							'Y/m/d', 'Y-m-d', 'Y.m.d', 'Y-m-d G:i:s',
							'custom',
						];

						if ( ! standardFormats.includes( format ) ) {
							const hasDatePlaceholder = /%[MDYHST]/.test( format ) || /[mdYHis]/.test( format );
							if ( ! hasDatePlaceholder ) {
								return true;
							}
						}
					}

					if ( ! format ) {
						return ! looksLikeDate( stringValue );
					}

					return ! tryParseDate( stringValue, filterData );
				},
				message: () => t( i18n.invalid_date.message ),
				details: () => t( i18n.invalid_date.details ),
				action: 'fix_date_format',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_date.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_date.group.title ),
					iconKey: 'date',
					color: 'warning',
					description: t( i18n.invalid_date.group.description ),
					actionable: false,
				},
			},
			invalid_time: {
				order: 20,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && context.field && context.field._data && context.field._data.filter === 'timeFormat',
				validateCell: ( value, context ) => {
					const stringValue = String( value ).trim();
					if ( ! stringValue ) {
						return false;
					}

					const { _data: { filterData } = {} } = context.field || {};
					if ( filterData && filterData.format ) {
						return ! tryParseTime( stringValue, filterData );
					}

					return ! looksLikeTime( stringValue );
				},
				message: () => t( i18n.invalid_time.message ),
				details: () => t( i18n.invalid_time.details ),
				action: 'fix_time_format',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_time.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_time.group.title ),
					iconKey: 'time',
					color: 'warning',
					description: t( i18n.invalid_time.group.description ),
					actionable: false,
				},
			},
			invalid_list: {
				order: 30,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) &&
					( ( context.field && context.field._data && context.field._data.filter === 'listJson' ) || ( context.field && context.field.type === 'list' ) || ( context.field && context.field._data && context.field._data.list_choices ) ),
				validateCell: ( value ) => {
					const stringValue = String( value ).trim();

					if ( ! stringValue ) {
						return false;
					}

					try {
						const obj = JSON.parse( stringValue );

						return ! _.isObject( obj );
					} catch ( e ) {
						return true;
					}
				},
				message: () => t( i18n.invalid_list.message ),
				details: () => t( i18n.invalid_list.details ),
				action: 'fix_json_format',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_list.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_list.group.title ),
					iconKey: 'list',
					color: 'warning',
					description: t( i18n.invalid_list.group.description ),
					actionable: false,
				},
			},
			invalid_notes: {
				order: 40,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) &&
					( ( context.field && context.field._data && context.field._data.filter === 'entryNotes' ) || ( context.field && context.field.type === 'notes' ) ),
				validateCell: ( value ) => {
					const stringValue = String( value ).trim();

					if ( ! stringValue ) {
						return false;
					}

					try {
						const obj = JSON.parse( stringValue );

						return ! _.isArray( obj ) || ( obj.length && ! _.get( obj, '0.note_type' ) );
					} catch ( e ) {
						return true;
					}
				},
				message: () => t( i18n.invalid_notes.message ),
				details: () => t( i18n.invalid_notes.details ),
				action: 'fix_json_format',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_notes.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_notes.group.title ),
					iconKey: 'notes',
					color: 'warning',
					description: t( i18n.invalid_notes.group.description ),
					actionable: false,
				},
			},
			duplicate: {
				order: 50,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ),
				validateColumn: ( context ) => {
					const { form, field, columnIndex, selectedColumnFields } = context;

					if ( ! isFieldMapped( field, form ) ) {
						return false;
					}

					if ( form.type === 'new' ) {
						const currentType = field.type;

						// Skip validation if field is not being imported
						if ( field.importEnabled === false ) {
							return false;
						}

						if ( ! currentType ||
							 currentType === ignoreFieldId ||
							 ! nonDuplicableTypes.includes( currentType ) ) {
							return false;
						}

						const duplicateCount = selectedColumnFields.filter( ( f, idx ) => {
							if ( idx === columnIndex ) return false;
							if ( f.ignore || f.importEnabled === false || ! f.type || f.type === ignoreFieldId ) return false;
							return f.type === currentType;
						} ).length;

						return duplicateCount > 0;
					}

					const currentFieldId = field.id;

					// Skip validation if field is not being imported
					if ( field.importEnabled === false ) {
						return false;
					}

					if ( ! currentFieldId ||
						 currentFieldId === defaultColumnField ||
						 currentFieldId === ignoreFieldId ) {
						return false;
					}

					const duplicateCount = selectedColumnFields.filter( ( f, idx ) => {
						if ( idx === columnIndex ) return false;
						if ( f.ignore || f.importEnabled === false || ! f.id || f.id === ignoreFieldId ) return false;
						return f.id === currentFieldId;
					} ).length;

					return duplicateCount > 0;
				},
				getColumnDetails: ( context ) => {
					const { form, field, columnIndex, selectedColumnFields, importData } = context;
					const columnName = importData[ 0 ] && importData[ 0 ][ columnIndex ] ? importData[ 0 ][ columnIndex ] : `Column ${ columnIndex + 1 }`;

					const fieldIdentifier = form.type === 'new' ? 'type' : 'id';
					const currentValue = field[ fieldIdentifier ];
					const duplicateColumns = selectedColumnFields
						.map( ( f, idx ) => {
							if ( idx === columnIndex || ! f[ fieldIdentifier ] || f[ fieldIdentifier ] === ignoreFieldId || f.ignore || f.importEnabled === false ) {
								return null;
							}
							if ( f[ fieldIdentifier ] === currentValue ) {
								const colName = importData[ 0 ] && importData[ 0 ][ idx ] ? importData[ 0 ][ idx ] : `Column ${ idx + 1 }`;
								return colName;
							}
							return null;
						} )
						.filter( col => col !== null );

					return {
						type: 'duplicate',
						severity: 'error',
						message: t( i18n.duplicate.message ),
						details: t( i18n.duplicate.details ).replace( '%s', duplicateColumns.join( ', ' ) ),
						columnName,
						sampleValue: duplicateColumns[ 0 ] || '',
						affectedCount: duplicateColumns.length + 1,
						totalCount: selectedColumnFields.length,
						action: 'unmap_duplicate',
					};
				},
				badgeText: () => t( i18n.duplicate.badge ),
				badgeModifier: 'error-badge-duplicate',
				group: {
					title: t( i18n.duplicate.group.title ),
					iconKey: 'duplicate',
					color: 'danger',
					description: t( i18n.duplicate.group.description ),
					actionable: true,
				},
			},
			invalid_email: {
				order: 60,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isEmailField( context.field, context.form ),
				validateCell: ( value ) => {
					const stringValue = String( value ).trim();
					if ( ! stringValue ) {
						return false;
					}
					return ! looksLikeEmail( stringValue );
				},
				message: ( context, stats, sampleValue ) => {
					const template = t( i18n.invalid_email.message );
					return template
						.replace( '%d', String( stats.count || 1 ) )
						.replace( '%s', sampleValue );
				},
				details: () => t( i18n.invalid_email.details ),
				action: 'review_email_data',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_email.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_email.group.title ),
					iconKey: 'email',
					color: 'warning',
					description: t( i18n.invalid_email.group.description ),
					actionable: false,
				},
			},
			rejected_email: {
				order: 70,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isEmailField( context.field, context.form ) && rejectablePatterns.length > 0,
				validateCell: ( value ) => {
					const stringValue = String( value ).trim().toLowerCase();
					if ( ! stringValue ) {
						return false;
					}
					return rejectablePatterns.some( pattern => stringValue.includes( pattern.toLowerCase() ) );
				},
				message: ( context, stats, sampleValue ) => {
					const template = t( i18n.rejected_email.message );
					return template
						.replace( '%d', String( stats.count || 1 ) )
						.replace( '%s', sampleValue );
				},
				details: () => {
					const patterns = rejectablePatterns.join( ', ' );
					const template = t( i18n.rejected_email.details );
					return template.replace( '%s', patterns );
				},
				action: 'review_email_data',
				severity: 'warning',
				badgeText: () => t( i18n.rejected_email.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.rejected_email.group.title ),
					iconKey: 'emailRejected',
					color: 'warning',
					description: t( i18n.rejected_email.group.description ),
					actionable: false,
				},
			},
			invalid_number: {
				order: 80,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isNumberField( context.field, context.form ),
				validateCell: ( value ) => isValueInvalidNumber( value ),
				message: () => t( i18n.invalid_number.message ),
				details: () => t( i18n.invalid_number.details ),
				action: 'review_number_data',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_number.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_number.group.title ),
					iconKey: 'number',
					color: 'warning',
					description: t( i18n.invalid_number.group.description ),
					actionable: false,
				},
			},
			invalid_url: {
				order: 90,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isUrlField( context.field, context.form ),
				validateCell: ( value ) => {
					const stringValue = String( value ).trim();
					if ( ! stringValue ) {
						return false;
					}
					return ! looksLikeUrl( stringValue );
				},
				message: () => t( i18n.invalid_url.message ),
				details: () => t( i18n.invalid_url.details ),
				action: 'review_url_data',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_url.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_url.group.title ),
					iconKey: 'url',
					color: 'warning',
					description: t( i18n.invalid_url.group.description ),
					actionable: false,
				},
			},
			invalid_phone: {
				order: 100,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isPhoneField( context.field, context.form ),
				validateCell: ( value ) => isValueInvalidPhone( value ),
				message: () => t( i18n.invalid_phone.message ),
				details: () => t( i18n.invalid_phone.details ),
				action: 'review_phone_data',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_phone.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_phone.group.title ),
					iconKey: 'phone',
					color: 'warning',
					description: t( i18n.invalid_phone.group.description ),
					actionable: false,
				},
			},
			invalid_ip: {
				order: 110,
				appliesTo: ( context ) => isFieldMapped( context.field, context.form ) && isIpField( context.field, context.form ),
				validateCell: ( value ) => isValueInvalidIp( value ),
				message: () => t( i18n.invalid_ip.message ),
				details: () => t( i18n.invalid_ip.details ),
				action: 'review_ip_data',
				severity: 'warning',
				badgeText: () => t( i18n.invalid_ip.badge ),
				badgeModifier: 'error-badge-warning',
				group: {
					title: t( i18n.invalid_ip.group.title ),
					iconKey: 'ip',
					color: 'warning',
					description: t( i18n.invalid_ip.group.description ),
					actionable: false,
				},
			},
		};

		return validationConfig;
	};

	const getValidationOrder = () => {
		const config = getValidationConfig();

		return Object.keys( config ).sort( ( a, b ) => ( config[ a ].order || 0 ) - ( config[ b ].order || 0 ) );
	};

	return {
		getValidationConfig,
		getValidationOrder,
		scanInvalidValues,
		isEmptyValidationValue,
	};
};
