	/**
	 * Display final statistics and call to action
	 *
	 * @return {Object} JSX markup
	 */
	displayFinishedState() {
		const { batchResponse: { progress, meta } } = this.state;
		const { importData: { form } } = this.props.context;
		const formId = form?.id || this.state.batchResponse?.form_id;

		const viewImportedRecordsButton = {
			automationId: 'view_imported_records',
			label: pluginData.localization.import_data.view_imported_records,
			action: () => window.location.href = `${ pluginData.gf_entries_url }&id=${ formId }`,
		};
		const startnewImportButton = {
			automationId: 'start_new_import',
			label: pluginData.localization.import_data.start_new_import,
			action: () => this.startNewImportJob(),
		};
		const downloadProfileButton = {
			automationId: 'download_import_profile_complete',
			label: pluginData.localization.configure.download_import_profile,
			action: () => this.handleDownloadProfile(),
		};
		const retryFailedRecordsButton = {
			automationId: 'retry_failed_records',
			label: replacePlaceholders(
				pluginData.localization.import_data.retry_failed_records,
				[ i18nFormatNumber( progress.error ) ]
			),
			action: () => this.retryFailedRecords( {
				goToConfigureStep: true,
			} ),
		};
		const remapRetryButton = {
			automationId: 'remap_retry_failed_records',
			label: replacePlaceholders(
				pluginData.localization.import_data.remap_retry_failed_records,
				[ i18nFormatNumber( progress.error ) ]
			),
			action: () => this.retryFailedRecords( {
				goToConfigureStep: false,
			} ),
		};

		let title;
		let automationId;
		let buttons;
		const errors = progress.error || 0;
		const skipped = progress.skipped || 0;
		const processed = progress.processed || 0;
		const total = meta.rows || progress.total || 0;
		const completedWithoutErrors = errors === 0 && ( ! total || processed + skipped >= total );

		// Completed without row errors, including rows skipped by conditional import.
		if ( completedWithoutErrors ) {
			title = pluginData.localization.import_data.import_complete;
			automationId = 'import_finished';
			buttons = [ viewImportedRecordsButton, startnewImportButton ];
		// No records were imported because all attempted rows failed.
		} else if ( processed === 0 ) {
			title = pluginData.localization.import_data.import_failed;
			automationId = 'import_finished_all_failed';

			buttons = [ retryFailedRecordsButton, remapRetryButton, startnewImportButton ];
		// Mixed result: some records imported and some errored.
		} else {
			title = pluginData.localization.import_data.import_complete_with_errors;
			automationId = 'import_finished_with_errors';

			buttons = [ viewImportedRecordsButton, retryFailedRecordsButton, remapRetryButton, startnewImportButton ];
		}

		if ( this.canDownloadProfile() ) {
			buttons.splice( 1, 0, downloadProfileButton );
		}

		return (
			<>
				<p data-automation-id={ automationId } className={ styles( 'title', 'is-4' ) }>
					{ title }
				</p>
				<p className={ styles( 'stats', 'is-size-5' ) }>
					{ this.getBatchFinalProgressReport() }
				</p>

				<div className={ styles( 'buttons', 'has-text-centered', 'block' ) }>
					{ buttons.map( ( button ) =>
						<span
							key={ `button-${ button.label }` }
							className={ styles( 'button', 'is-link' ) }
							data-automation-id={ button.automationId }
							role="button"
							tabIndex={ 0 }
							onClick={ button.action }
							onKeyDown={ ( e ) => e.keyCode === 13 ? button.action() : null }
						>
							{ button.label }
						</span>,
					) }
				</div>
			</>
		);
	}

